// ===== Helpers =====
function toNumber(v) {
    if (v == null) return null;
    if (typeof v === 'number') return v;
    const n = Number(String(v).trim());
    return Number.isFinite(n) ? n : null;
}

function normalizeOrderTypeText(v) {
    if (v == null) return null;
    const t = String(v).trim().toLowerCase();
    if (["out", "issue", "export", "dispatch"].includes(t)) return "out";
    if (["in", "receive", "import", "inbound"].includes(t)) return "in";
    return t; // คืนค่าที่เหลือไว้ (เช่น in/out อยู่แล้ว)
}

// map code <-> text
function codeToOrderType(code) {
    if (!code) return null;
    const c = String(code).trim().toUpperCase();
    if (c === "V") return "in";
    if (c === "P") return "out";
    return null; // ไม่รู้จักโค้ด
}

function orderTypeToCode(type) {
    if (!type) return null;
    const t = String(type).trim().toLowerCase();
    if (t === "in") return "V";
    if (t === "out") return "P";
    return t.toUpperCase(); // คงค่าเดิมไว้หากไม่ใช่ in/out
}

