        orderType = codeToOrderType(parts[2]) || normalizeOrderTypeText(parts[2]);
        mappedOrderType = orderTypeToCode(orderType);
    } else {
        node.error("รูปแบบสตริงไม่ถูกต้อง (ต้องเป็น PRODUCT|QTY|V/P)", msg);
